const {chromium}=require(process.env.PLAYWRIGHT_PATH||'playwright'),assert=require('node:assert/strict');
(async()=>{const browser=await chromium.launch({headless:true,executablePath:process.env.CHROME_PATH});const page=await browser.newPage({viewport:{width:1280,height:900}}),errors=[];page.on('pageerror',e=>errors.push(e.message));await page.goto('http://localhost:4173');await page.click('#play');await page.keyboard.press('ArrowLeft');assert.equal(await page.getAttribute('#choose-goku','aria-pressed'),'true');await page.waitForTimeout(200);await page.locator('.screen').screenshot({path:__dirname+'/preview-five-characters.png'});await page.setViewportSize({width:390,height:844});assert(await page.evaluate(()=>{const a=document.querySelector('.screen').getBoundingClientRect(),b=document.querySelector('#character-picker').getBoundingClientRect();return b.top>=a.top&&b.bottom<=a.bottom+1&&document.documentElement.scrollWidth<=innerWidth;}));console.log('PASS five characters fit desktop and mobile');await page.setViewportSize({width:1280,height:900});await page.click('#character-start');await page.waitForTimeout(400);await page.keyboard.press('KeyJ');await page.waitForTimeout(50);assert.equal(await page.evaluate(()=>shots.length),0);
for(const weapon of ['kame','superKame']){await page.evaluate(()=>{world.enemies=[];shots=[];player.fire=0;const it={type:'dragonball',x:0,y:0};items.push(it);power(it);});await page.keyboard.press('KeyJ');await page.waitForTimeout(50);assert.equal(await page.evaluate(()=>shots[0].weapon),weapon);}console.log('PASS no attack, Kamehameha, Super Saiyan Kamehameha');await page.keyboard.press('Space');await page.waitForTimeout(120);assert(await page.evaluate(()=>!player.ground));await page.evaluate(()=>{player.inv=0;state='paused';draw();});await page.locator('#game').screenshot({path:__dirname+'/preview-goku-nimbus.png'});console.log('PASS airborne Super Saiyan and Nimbus render');await page.reload();await page.click('#continue');assert.equal(await page.evaluate(()=>player.character),'goku');assert.equal(await page.evaluate(()=>player.power),2);assert.deepEqual(errors,[]);console.log('PASS save restores Goku, no browser errors');await browser.close();})().catch(e=>{console.error(e);process.exit(1);});
